--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,45 @@
+import { AppError } from "../errors.js";
+import { isDate } from "../dates.js";
+import { parseCsv } from "./csv.js";
+import { importSales } from "../domain/sales.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+function invalid(row, reason) {
+  throw new AppError("sales_row", { row, reason });
+}
+
+/** Parses and validates sales CSV, then imports the whole file atomically. */
+export function importSalesCsv(store, text, { at }) {
+  const lines = text.split(/\r?\n/);
+  let header;
+  const rows = [];
+  for (const [index, line] of lines.entries()) {
+    if (!line.trim()) continue;
+    const row = index + 1;
+    if (!/^(?:[^",]*|"(?:[^"\r\n]|"")*")(?:,(?:[^",]*|"(?:[^"\r\n]|"")*"))*$/.test(line))
+      invalid(row, "malformed CSV");
+    const fields = parseCsv(line)[0].map((field) => field.trim());
+    if (!header) {
+      header = fields;
+      if (header.length !== HEADER.length || HEADER.some((key) => !header.includes(key)))
+        invalid(row, "expected columns ticket,soldAt,dishId,qty");
+      continue;
+    }
+    if (fields.length !== header.length) invalid(row, "wrong number of fields");
+    const values = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    const dishId = Number(values.dishId);
+    const qty = Number(values.qty);
+    if (!values.ticket) invalid(row, "ticket is required");
+    if (!/^[0-9]+$/.test(values.dishId) || !Number.isSafeInteger(dishId) || dishId < 1)
+      invalid(row, "invalid dishId");
+    if (!/^[0-9]+$/.test(values.qty) || !Number.isSafeInteger(qty) || qty < 1)
+      invalid(row, "qty must be a positive whole number");
+    if (!/^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/.test(values.soldAt)
+      || !isDate(values.soldAt.slice(0, 10)) || !Number.isFinite(Date.parse(values.soldAt)))
+      invalid(row, "soldAt must be an ISO instant");
+    rows.push({ row, ticket: values.ticket, soldAt: new Date(values.soldAt).toISOString(), dishId, qty });
+  }
+  if (!header) invalid(1, "missing header");
+  return importSales(store, rows, { at });
+}
